-- 14. JOB POSITIONS
INSERT INTO `job_positions` (`id`, `job_code`, `title`, `department_id`, `branch_id`, `position_id`, `quantity`, `salary_range_min`, `salary_range_max`, `requirements`, `description`, `deadline`, `status`, `created_by`, `created_at`) VALUES
(1, 'JOB-2026-001', 'Kỹ Sư Trí Tuệ Nhân Tạo & Phân Tích Bán Lẻ (AI & Retail Data Scientist)', 3, 1, 5, 2, 30000000, 48000000, 'Tối thiểu 3 năm kinh nghiệm Python, PyTorch/TensorFlow, Big Data, Demand Forecasting bán lẻ.', 'Xây dựng thuật toán AI gợi ý giỏ hàng thông minh, tối ưu giá linh hoạt (Dynamic Pricing) chuỗi siêu thị.', '2026-11-30', 'open', 1, NOW()),
(2, 'JOB-2026-002', 'Giám Đốc Cửa Hàng Flagship Bitexco Q1 (Store Manager)', 4, 2, 8, 3, 22000000, 35000000, 'Tốt nghiệp Đại học, ít nhất 4 năm quản lý chuỗi bán lẻ cao cấp quy mô > 50 nhân sự.', 'Chịu trách nhiệm toàn diện doanh số P&L, trải nghiệm dịch vụ khách hàng tại trung tâm thương mại Bitexco.', '2026-10-31', 'open', 1, NOW()),
(3, 'JOB-2026-003', 'Trưởng Nhóm Điều Phối Logistics Vùng Mekong', 5, 4, 6, 2, 18000000, 26000000, 'Có kinh nghiệm điều hành kho lạnh và mạng lưới xe tải giao hàng chặng cuối Tây Nam Bộ.', 'Giám sát điều vận đội xe, tối ưu thời gian giao hàng tươi sống từ kho Cần Thơ về 13 tỉnh Mekong.', '2026-11-15', 'open', 1, NOW()),
(4, 'JOB-2026-004', 'Kỹ Sư DevOps / Cloud & Security Senior', 3, 1, 9, 2, 26000000, 38000000, 'Thành thạo Kubernetes, Docker, CI/CD pipeline, AWS/GCP, giám sát hệ thống 24/7.', 'Thiết kế kiến trúc hạ tầng đám mây có độ sẵn sàng cao phục vụ 500+ điểm bán lẻ toàn quốc.', '2026-10-31', 'open', 1, NOW()),
(5, 'JOB-2026-005', 'Chuyên Viên Quản Lý Chuỗi Cung Ứng Hải Phòng (Port Logistics)', 5, 5, 14, 3, 16000000, 22000000, 'Hiểu biết sâu sắc về thủ tục hải quan cảng biển, khai thác kho CFS và vận tải liên phương thức.', 'Điều phối container hàng nhập khẩu từ Cảng Đình Vũ và Lạch Huyện về tổng kho miền Bắc.', '2026-11-30', 'open', 1, NOW()),
(6, 'JOB-2026-006', 'Chuyên Viên Truyền Thông & Tiếp Thị Số (Digital Marketing Lead)', 7, 2, 10, 2, 18000000, 28000000, 'Có kinh nghiệm chạy chiến dịch Performance Marketing chuỗi bán lẻ ngân sách > 500 triệu/tháng.', 'Xây dựng chiến dịch truyền thông đa kênh Omni-channel thu hút 1 triệu người tiêu dùng mới.', '2026-10-15', 'open', 1, NOW()),
(7, 'JOB-2026-007', 'Chuyên Viên Pháp Chế Hợp Đồng Thương Mại', 9, 1, 12, 1, 18000000, 25000000, 'Cử nhân Luật, có thẻ luật sư, 3 năm kinh nghiệm đàm phán hợp đồng thuê mặt bằng bán lẻ.', 'Rà soát hợp đồng nhượng quyền, mặt bằng kinh doanh và xử lý các tranh chấp thương mại.', '2026-11-15', 'open', 1, NOW()),
(8, 'JOB-2026-008', 'Chuyên Viên Chăm Sóc Khách Hàng Cao Cấp (VIP Customer Care)', 8, 2, 13, 4, 13000000, 18000000, 'Giọng nói chuẩn, khéo léo xử lý tình huống, ưu tiên từng làm việc tại khách sạn 5 sao hoặc sàn TMĐT.', 'Chăm sóc hội viên kim cương, giải quyết phản hồi chất lượng và khảo sát NPS định kỳ.', '2026-10-30', 'open', 1, NOW());

